.denomination {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.value {
  font-size: 18px;
  font-weight: 900;
}

.kind {
  color: #6b7280;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.controls {
  display: grid;
  grid-template-columns: 34px 1fr 34px;
  gap: 6px;
  margin-top: 10px;
}

.controls button {
  height: 32px;
  border: 0;
  border-radius: 6px;
  background: #111827;
  color: white;
