  font-weight: 900;
  cursor: pointer;
}

.controls input {
  width: 100%;
  height: 32px;
  box-sizing: border-box;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  text-align: center;
  font-weight: 800;
}

.line-total {
  margin-top: 8px;
  text-align: right;
  font-size: 12px;
  color: #374151;
