.line-total b {
  color: #111827;
}

.footer {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}

.secondary {
  height: 36px;
  padding: 0 14px;
  border: 1px solid #d1d5db;
  border-radius: 7px;
  background: white;
  font-weight: 800;
  cursor: pointer;
