@media (max-width: 520px) {
  .denomination-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .header {
    flex-direction: column;
  }
  .total-box {
    width: 100%;
    box-sizing: border-box;
  }
}

