const DEFAULT_DENOMINATIONS = [500, 200, 100, 50, 20, 10, 5, 2, 1, 0.5, 0.2, 0.1, 0.05, 0.02, 0.01];
let state = {
  lines: []
};
function money(value) {
  return Number(value || 0).toFixed(2);
}
function normalizeLines(lines) {
  const byValue = new Map((lines || []).map(row => [Number(row.denominationValue), Number(row.quantity || 0)]));
  return DEFAULT_DENOMINATIONS.map(value => {
    const quantity = byValue.get(Number(value)) || 0;
    return {
      denominationValue: value,
      quantity,
      amount: Number((value * quantity).toFixed(2))
    };
  });
}
function total(lines) {
  return (lines || []).reduce((sum, row) => sum + Number(row.amount || 0), 0);
}
function publish() {
  const totalAmount = total(state.lines);
  appsmith.updateModel({
    lines: state.lines,
    total: totalAmount
  });
  appsmith.triggerEvent("onCashCountChange");
}
function setQty(value, quantity) {
  state.lines = state.lines.map(row => {
    if (Number(row.denominationValue) !== Number(value)) return row;
    const qty = Math.max(0, Number(quantity || 0));
    return {
      ...row,
      quantity: qty,
      amount: Number((Number(row.denominationValue) * qty).toFixed(2))
    };
  });
  render();
  publish();
}
function clearAll() {
  state.lines = normalizeLines([]);
  render();
  publish();
}
function render() {
  const model = appsmith.model || {};
  const currency = model.currency || "EUR";
  document.getElementById("title").innerText = model.title || "Opening Cash";
  document.getElementById("grandTotal").innerText = `${money(total(state.lines))} ${currency}`;
  document.getElementById("denominationGrid").innerHTML = state.lines.map(row => {
    const value = Number(row.denominationValue);
    const isCoin = value < 5;
    return `
      <div class="tile ${isCoin ? "coin" : "banknote"}">
        <div class="denomination">
          <div class="value">${money(value)}</div>
          <div class="kind">${isCoin ? "Coin" : "Note"}</div>
        </div>

        <div class="controls">
          <button data-action="minus" data-value="${value}">-</button>
          <input data-value="${value}" value="${row.quantity}" inputmode="numeric" />
          <button data-action="plus" data-value="${value}">+</button>
        </div>

        <div class="line-total">Line: <b>${money(row.amount)} ${currency}</b></div>
      </div>
    `;
  }).join("");
  document.querySelectorAll("button[data-action]").forEach(btn => {
    btn.onclick = () => {
      const value = Number(btn.dataset.value);
      const current = state.lines.find(row => Number(row.denominationValue) === value);
      const qty = Number(current?.quantity || 0);
      setQty(value, btn.dataset.action === "plus" ? qty + 1 : qty - 1);
    };
  });
  document.querySelectorAll("input[data-value]").forEach(input => {
    input.onchange = () => {
      setQty(Number(input.dataset.value), Number(input.value || 0));
    };
  });
  document.getElementById("clearBtn").onclick = clearAll;
}
appsmith.onReady(() => {
  state.lines = normalizeLines(appsmith.model?.lines || []);
  render();
});
appsmith.onModelChange(model => {
  state.lines = normalizeLines(model?.lines || []);
  render();
});

